#include <iostream>
#include <string>
#include <vector>
using namespace std;

class Cat {
protected:
    string name;
    int age;
public:
    Cat(string n, int a) : name(n), age(a) {}
    string getName() { return name; }
    void greet() {
        cout << "我是" << name << "，今年 " << age << " 岁喵" << endl;
    }
};

int main() {
    int n = 0;
    cin >> n;

    vector<Cat> roster;
    for (int i = 0; i < n; i++) {
        int a = 0;
        cin >> a;
        roster.push_back(Cat("{name}", a));
    }

    cout << "名册上一共 " << roster.size() << " 只" << endl;
    for (Cat& c : roster) {
        c.greet();
    }
    return 0;
}
